      <div style="font-size:13px;color:#64748b;">In draft ${b.days_in_draft} day(s) — $${b.total.toFixed(2)}</div>
    </div>`).join('');

const subject = `${item.attorney_name} has ${bills.length} pre-bill(s) stuck in draft`;

const bodyHtml = `
    <div style="color:#334155;font-size:14px;margin-bottom:18px;">${escapeHtml(item.attorney_name)} (${escapeHtml(item.attorney_email)}) has ${bills.length} draft pre-bill(s) that have been sitting unreviewed for a while (total $${total.toFixed(2)}):</div>
    ${rowsHtml}
    <a href="${BILLING_URL}" style="display:inline-block;background:#dc2626;color:#ffffff;text-decoration:none;font-size:14px;font-weight:600;padding:10px 18px;border-radius:6px;margin-top:22px;">Review in Clio →</a>`;

