${textLines.join('\n')}

Review directly in Clio:
${BILLING_URL}

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: PARTNER_EMAIL,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: textBody,
  email_html: emailShell('#dc2626', 'Escalation', subject, bodyHtml),
