const item = $input.first().json;
const bills = item.bills;
const total = bills.reduce((s, b) => s + b.total, 0);
const textLines = bills.map(b => `  • ${b.matter_ref} — ${b.client_name} — $${b.total.toFixed(2)} — in draft ${b.days_in_draft} day(s)`);

// This attorney's bills can be a mix of 'reminder' and 'urgent' tier -- label the email by the
// most urgent tier present so the subject and header color reflect the most pressing item.
const mostUrgent = bills.some(b => b.tier === 'urgent') ? 'urgent' : 'reminder';
const TIER_COPY = { reminder: 'A friendly nudge', urgent: 'An urgent reminder' };
const headerColor = mostUrgent === 'urgent' ? '#ea580c' : '#f59e0b';

const rowsHtml = bills.map(b => `
    <div style="border-bottom:1px solid #e2e8f0;padding:12px 0;">
