You have ${bills.length} draft pre-bill(s) still waiting for your review (total $${total.toFixed(2)}):

${textLines.join('\n')}

Review and finalize in Clio:
${BILLING_URL}

— ${FIRM_NAME} Billing System`;

return [{ json: {
  ...item,
  channel: 'email',
  recipient: item.attorney_email,
  from_email: FIRM_FROM_EMAIL,
  subject,
  message: textBody,
